fn author<'a>(&'a self) -> Option<Mailbox<'a>> {
    self.from
        .as_ref()
        .or(self.sender.as_ref())
        .map(|recipient| Mailbox::from(&recipient.mailbox))
}

fn reply_to_recipients<'a>(&'a self) -> Option<impl IntoIterator<Item = Mailbox<'a>>> {
    self.reply_to
        .as_ref()
        .map(|recipients| &recipients.0)
        .map(|recipients| {
            recipients
                .iter()
                .map(|recipient| Mailbox::from(&recipient.mailbox))
        })
}
